      const offers = S.offers.filter(o => o.cust === S.custId).map(o => `<div class="tinted-row ${o.status === 'open' ? 'blue' : 'gray'}"><span style="flex:1"><b>${o.id}</b> · ${esc(locName(o.from))} → ${esc(locName(o.to))} · ${o.pallets} ${esc(T('пал.', 'Pal.', 'pal.', 'пал.'))} · <b>${kzt(o.gross)}</b><div class="sub">${esc(T('цена зафиксирована до', 'Preis fix bis', 'price locked until', 'баға бекітілген'))} ${fd(o.until)}</div></span>${chip(OFST[o.status][0], OFST[o.status][1])}<button class="btn sm grey" data-act="bkDoc" data-id="${o.id}">${esc(T('Образец', 'Muster', 'Sample', 'Үлгі'))}</button>${o.status === 'open' ? `<button class="btn sm primary" data-act="bkUseOffer" data-id="${o.id}">${esc(T('Забронировать по КП', 'Mit Angebot buchen', 'Book with the offer', 'КҰ бойынша брондау'))}</button>` : ''}</div>`).join('') || '<p class="note">—</p>';
      const cts = S.contracts.filter(c => c.cust === S.custId && c.status !== 'void').map(c => `<div class="tinted-row ${c.status === 'signed' ? 'green' : c.status === 'sent' ? 'yellow' : 'gray'}" data-ct-row="${c.id}"><span style="flex:1"><b>${c.id}</b> · ${esc(CTKIND[c.kind])} · ${esc(c.tpl)} · ${fd(c.from)} – ${c.to ? fd(c.to) : '∞'}<div class="sub">SHA-256 ${c.sha.slice(0, 16)}… ${c.signed ? '· ' + esc(T('подписан', 'unterschrieben', 'signed', 'қол қойылды')) + ' ' + fd(c.signed) + ' · ' + esc(c.signer) : ''}</div></span>${chip(CTST[c.status][0], CTST[c.status][1])}<button class="btn sm grey" data-act="bkCtOpen" data-id="${c.id}">${esc(T('Открыть текст', 'Text öffnen', 'Open text', 'Мәтінді ашу'))}</button>${c.status === 'sent' ? `<button class="btn sm primary" data-act="bkSign" data-id="${c.id}"${CT.read[c.id] ? '' : ` disabled title="${esc(T('Сначала откройте текст договора', 'Zuerst den Vertragstext öffnen', 'Open the contract text first', 'Алдымен шарт мәтінін ашыңыз'))}"`}>${esc(T('Подписать ЭЦП (демо NCALayer)', 'Signieren (Demo-NCALayer)', 'Sign (demo NCALayer)', 'ЭЦҚ қою (демо NCALayer)'))}</button>` : ''}</div>`).join('') || `<p class="note" data-no-ct>${esc(T('Договоров пока нет — их готовит отдел продаж.', 'Noch keine Verträge – der Vertrieb bereitet sie vor.', 'No contracts yet — sales prepares them.', 'Әзірге шарт жоқ – оларды сату бөлімі дайындайды.'))}</p>`;
      const fwLine = fw ? `<p class="note" data-fw>${chip('green', T('Действует рамочный договор · ', 'Rahmenvertrag aktiv · ', 'Active framework contract · ', 'Үлгілік шарт әрекетте · ') + fw.id)}</p>` : `<p class="note" data-no-fw>${esc(T('Нет действующего рамочного договора — бронирования только по предоплате.', 'Kein aktiver Rahmenvertrag – Buchungen nur gegen Vorkasse.', 'No active framework contract — bookings are prepaid only.', 'Әрекеттегі үлгілік шарт жоқ – брондау тек алдын ала төлеммен.'))}</p>`;
      return `<div class="kpi-row k4"><div class="kpi-tile"><div><div class="value">${mine.length}</div><div class="label">${esc(T('бронирований', 'Buchungen', 'bookings', 'брондау'))}</div></div></div><div class="kpi-tile"><div><div class="value">${mine.filter(b => b.status === 'new').length}</div><div class="label">${esc(T('ждут подтверждения', 'warten auf Bestätigung', 'awaiting confirmation', 'растауды күтеді'))}</div></div></div><div class="kpi-tile"><div><div class="value">${S.offers.filter(o => o.cust === S.custId && o.status === 'open').length}</div><div class="label">${esc(T('действующих КП', 'gültige Angebote', 'valid offers', 'жарамды КҰ'))}</div></div></div><div class="kpi-tile"><div><div class="value">${fw ? fw.id : '—'}</div><div class="label">${esc(fw ? T('рамочный договор · оплата по счёту', 'Rahmenvertrag · auf Rechnung', 'framework contract · on account', 'үлгілік шарт · шот бойынша') : T('нет рамочного договора → предоплата', 'kein Rahmenvertrag → Vorkasse', 'no framework contract → prepayment', 'үлгілік шарт жоқ → алдын ала төлем'))}</div></div></div></div>
${KIT.table(['№', T('Маршрут', 'Route', 'Route', 'Маршрут'), T('Зона', 'Zone', 'Zone', 'Аймақ'), T('Груз', 'Ladung', 'Cargo', 'Жүк'), T('Отправление', 'Abfahrt', 'Departure', 'Жөнелту'), T('Цена', 'Preis', 'Price', 'Баға'), T('Статус', 'Status', 'Status', 'Күйі'), ''], rows, { cols: 8, empty: T('Бронирований пока нет', 'Noch keine Buchungen', 'No bookings yet', 'Брондаулар жоқ') })}
<div class="card tcard" data-ex-table><div class="card-head">${esc(T('Экспресс-заявки', 'Expressanfragen', 'Express requests', 'Экспресс өтінімдер'))}</div><table class="table"><thead><tr><th>№</th><th>${esc(T('Откуда → куда', 'Von → nach', 'From → to', 'Қайдан → қайда'))}</th><th>${esc(T('Доставить к', 'Zustellen bis', 'Deliver by', 'Жеткізу мерзімі'))}</th><th>${esc(T('решение до', 'Entscheidung bis', 'decision by', 'шешім мерзімі'))}</th><th>${esc(T('надбавка за экспресс', 'Expresszuschlag', 'express surcharge', 'экспресс үстемесі'))}</th><th>${esc(T('Итого', 'Gesamt', 'Total', 'Барлығы'))}</th><th>${esc(T('Статус', 'Status', 'Status', 'Күйі'))}</th></tr></thead><tbody>${exs || `<tr><td colspan="7" class="empty">${esc(T('Экспресс-заявок нет', 'Keine Expressanfragen', 'No express requests', 'Экспресс өтінім жоқ'))}</td></tr>`}</tbody></table></div>
<div class="grid2 eq">${card(T('Коммерческие предложения', 'Angebote', 'Offers', 'Коммерциялық ұсыныстар'), offers)}${card(T('Договоры и электронная подпись', 'Verträge und elektronische Signatur', 'Contracts and e-signature', 'Шарттар және электрондық қолтаңба'), `${fwLine}${CT.msg ? `<p class="note" data-ct-msg>${chip('green', CT.msg)}</p>` : ''}<p class="note">${esc(T('Подпись создаётся локально в NCALayer; на сервер уходит только CMS-подпись хеша текста.', 'Die Signatur entsteht lokal in NCALayer; nur die CMS-Signatur des Text-Hashs geht an den Server.', 'The signature is created locally in NCALayer; only the CMS signature of the text hash reaches the server.', 'Қолтаңба NCALayer-де жергілікті жасалады; серверге тек мәтін хешінің CMS қолтаңбасы жіберіледі.'))}</p>${cts}`)}</div>`;
