    bkSign: d => { if (signContract(d.id, me().contact + ' (' + T('ЭЦП НУЦ РК, демо', 'NCA-Signatur, Demo', 'NCA e-signature, demo', 'ҚР ҰКО ЭЦҚ, демо') + ')')) CT.msg = d.id + ' · ' + T('Договор подписан; подпись проверена.', 'Vertrag unterschrieben; Signatur geprüft.', 'Contract signed; signature verified.', 'Шартқа қол қойылды; қолтаңба тексерілді.'); render(); },
    bkCancelAsk: d => { B.askCancel = d.id; render(); },
    bkCancelNo: () => { B.askCancel = ''; render(); },
    bkCancel: d => { const b = S.bookings.find(x => x.id === d.id); if (b && b.status === 'new') { b.status = 'cancelled'; b.reason = T('отменено клиентом', 'vom Kunden storniert', 'cancelled by the customer', 'клиент болдырмады'); (b.hist = b.hist || []).push({ at: NOW.toISOString(), st: 'cancelled', who: 'customer', why: b.reason }); const e = b.express_id && (S.express || []).find(x => x.id === b.express_id); if (e && e.status === 'pending') { e.status = 'rejected'; b.exSt = 'rejected'; e.log.push({ t: fdt(NOW).slice(-5), text: T('Отменено клиентом', 'Vom Kunden storniert', 'Cancelled by the customer', 'Клиент болдырмады') }); } audit('Portal', b.id, 'Booking cancelled'); } B.askCancel = ''; render(); },
    bkStreet: d => { B[d.pre + 'Street'] = d.v; B[d.pre + 'Book'] = ''; B.done = null; render(); },
    bkLineDel: d => { B.lines.splice(+d.v, 1); render(); },
    bkSaveAddr: d => { const pre = d.pre, ac = pre === 'p' ? pa() : da(); if (ac.st !== 'ok') return; const cu = me(); cu.book.push({ id: 'A' + (cu.book.length + 1) + '-' + clockNow().getTime().toString(36), label: B[pre + 'Site'].trim() || ac.street + ' ' + B[pre + 'House'], city: B[pre + 'City'], street: ac.street, house: B[pre + 'House'], check: 'ok', hours: B[pre + 'Hours'].trim() || '09:00–18:00' }); B.savedAddr = pre; audit('Portal', cu.id, 'Address saved', locName(B[pre + 'City'])); toast(T('Адрес сохранён', 'Adresse gespeichert', 'Address saved', 'Мекенжай сақталды')); },
    bkQuote: () => { if (B.offer) return; const p = price(), today = NOW.toISOString().slice(0, 10), until = addD(today, 14), id = 'KP-26-' + String(S.offers.reduce((m, x) => Math.max(m, +String(x.id).replace(/\D/g, '').slice(-4) || 0), 0) + 1).padStart(4, '0');
      const o = { id, cust: S.custId, from: B.pCity, to: B.dCity, zone: B.zone, pallets: +B.pallets || 1, kg: +B.kg || 0, dg: dgBody(), insured: B.insured, declared: B.insured ? +B.declared || 0 : 0, express: B.express, gross: p.gross, issued: today, until, status: 'open', src: 'portal' };
      S.offers.unshift(o); B.offer = o.id; B.quoteMsg = o.id + ' · ' + T('КП', 'Angebot', 'Quote', 'КҰ') + ' · ' + kzt(o.gross) + ' · ' + T('цена зафиксирована до ', 'Preis fixiert bis ', 'price locked until ', 'баға бекітілген: ') + fd(until); audit('Portal', o.id, 'Quote locked', kzt(o.gross)); render(); },
